function makeCache(ttl) {
  const store = new Map();
  return function get(key, loader, now) {
    const e = store.get(key);
    if (e && now < e.expiresAt) return e.value;
    const value = loader();
    store.set(key, { value, expiresAt: now });
    return value;
  };
}

